"""System Design round 3: new lessons 501-508 (topic ids 501-520 are reserved for System Design extras).

Run:  python3 scripts/authoring/more3/sd.py   -> writes scripts/authored/sd-extra.json
Every number in a worked example is derived in the text; India examples are labelled illustrative.
"""
import json, os, sys
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'more2'))
from common import mc, order, est, text, diagram, flash, src, see, topic, deep  # noqa: E402


def worked(tid, n, title, body, teaches, steps, note):
    c = text(tid, n, title, body, teaches)
    c['steps'] = steps
    c['note'] = note
    return c


def tradeoff(id, concept, prompt, constraints, approaches, correct, rationales, right, wrong, conflicts, expl):
    return {"id": id, "concept": concept, "type": "tradeoff", "prompt": prompt, "constraints": constraints,
            "approaches": [{"id": k, "label": l, "description": d} for k, l, d in approaches],
            "correctApproachId": correct,
            "rationaleOptions": [{"id": k, "label": l} for k, l in rationales],
            "correctRationaleIds": right, "distractorRationaleIds": wrong,
            "rationaleConflicts": conflicts, "explanation": expl}


def predict(title, prompt, choices, correct, reveal, setup=None, kind='predict'):
    it = {"kind": kind, "title": title, "prompt": prompt,
          "choices": [{"id": k, "label": l, "feedback": f} for k, l, f in choices],
          "correctId": correct, "reveal": reveal}
    if setup:
        it["setup"] = setup
    return it


