def check():
    """Print option-length and absolute-word tells for the new MCQs."""
    import re
    ABS = re.compile(r"\b(always|never|entirely|completely|forever|guarantee[sd]?|impossible|at all|whole|automatically|instantly|every)\b", re.I)
    n = longest = 0
    for t in T:
        for q in t['questions']:
            if q['type'] != 'multiple_choice':
                continue
            n += 1
            c = q['correctChoiceIds'][0]
            right = next(x['label'] for x in q['choices'] if x['id'] == c)
            others = [x['label'] for x in q['choices'] if x['id'] != c]
            if all(len(right) > len(o) for o in others):
                longest += 1
                print('  longest:', q['id'], len(right), max(map(len, others)))
            for o in others:
                if ABS.search(o):
                    print('  absolute distractor:', q['id'], o)
    print(f'MCQs {n}, correct uniquely longest {longest}')


if __name__ == '__main__':
    check()
    out = os.path.join(os.path.dirname(__file__), '..', '..', 'authored', 'sd-extra.json')
    with open(out, 'w') as f:
        json.dump(T, f, ensure_ascii=False, indent=1)
        f.write('\n')
    print('wrote', os.path.relpath(out), [t['id'] for t in T])
